Setting a timeout to 0 disables it:

```ts
// playwright.config.ts
import { defineConfig } from '@playwright/test';

export default defineConfig({
  globalTimeout: 0,          // whole run, no limit
  timeout: 0,                // each test, no limit
  expect: {
    timeout: 0,              // assertions wait forever
  },
  use: {
    actionTimeout: 0,        // click, fill, etc.
    navigationTimeout: 0,    // goto, waitForURL, etc.
  },
});
```

Call `test.setTimeout(0)` inside that test:

```ts
test('long data migration check', async ({ page }) => {
  test.setTimeout(0);
  // ...
});
```
